package com.trombokendu.chronos.analytics;import java.time.*;import java.util.*;public final class DuplicateRule implements AnomalyRule{private final Set<String> fingerprints=new HashSet<>();public Optional<String> check(double a,String c,String d){String k=String.format(Locale.ROOT,"%.2f|%s|%s",a,c,d==null?"":d.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]",""));return fingerprints.add(k)?Optional.empty():Optional.of("Possible duplicate transaction");}}
